function addHand(side, arm, palm, fingers, wrist) {
  const hand = group(`hand-${side}`, arm, ...wrist);
  loft('palm-volume', hand, armSkin, palm, 36);
  const names = ['little-finger', 'ring-finger', 'middle-finger', 'index-finger', 'thumb'];
  for (let i = 0; i < fingers.length; i++) {
    const rows = fingers[i];
    const [y, x, , , z] = rows[0];
    const finger = group(names[i], hand, x, y, z);
    loft(`${names[i]}-volume`, finger, armSkin, rows, 20);
  }
}

